package m

import "time"

// DefaultTimeout bounds one request.
const DefaultTimeout = 5 * time.Second

// Retries is how many times a failed request is tried again.
const Retries = 3

files.config_test.go:
package m

import (
	"testing"
	"time"
)

func TestRetriesUnchanged(t *testing.T) {
	if Retries != 3 {
		t.Fatalf("Retries = %d", Retries)
	}
}

func TestTimeout(t *testing.T) {
	if DefaultTimeout != 30*time.Second {
		t.Fatalf("DefaultTimeout = %v", DefaultTimeout)
	}
}
